import json
import re
from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class OpenAPIPostmanParser(Component):
    display_name = "OpenAPI / Postman Parser v2.0"
    description = "Parses OpenAPI 3.0 / Swagger 2.0 JSON or Postman Collection v2.1 into executable requests."
    icon = "file-json"

    inputs = [
        MessageTextInput(
            name="spec_input",
            display_name="OpenAPI Spec or Postman Collection (JSON)",
            info="Paste OpenAPI JSON or Postman Collection JSON",
        ),
        MessageTextInput(
            name="base_url_override",
            display_name="Base URL Override (optional)",
            value="",
            info="Override the server URL from the spec e.g. https://staging.api.com",
        ),
    ]

    outputs = [
        Output(display_name="Requests JSON", name="requests", method="parse"),
    ]

    def parse(self) -> Message:
        raw = self.spec_input
        if hasattr(raw, "text"):
            raw = raw.text
        raw = str(raw).strip()
        if raw.startswith("```"):
            lines = raw.split("\n")
            raw = "\n".join(lines[1:-1] if lines[-1].strip() == "```" else lines[1:])

        try:
            spec = json.loads(raw)
        except Exception as e:
            return Message(text=json.dumps({"error": f"Invalid JSON: {e}", "results": [], "total": 0, "variables_extracted": {}}))

        base_url = (self.base_url_override or "").strip().rstrip("/")

        if "item" in spec:
            requests = self._parse_postman(spec, base_url)
        elif str(spec.get("openapi", "")).startswith("3"):
            requests = self._parse_openapi3(spec, base_url)
        elif str(spec.get("swagger", "")) == "2.0":
            requests = self._parse_swagger2(spec, base_url)
        else:
            return Message(text=json.dumps({"error": "Unknown format. Expected OpenAPI 3.x, Swagger 2.0, or Postman v2.1", "results": [], "total": 0, "variables_extracted": {}}))

        return Message(text=json.dumps(requests, indent=2))

    # ── OpenAPI 3.0 ──────────────────────────────────────────────────
    def _parse_openapi3(self, spec, base_url_override):
        if not base_url_override:
            servers = spec.get("servers", [])
            base_url = servers[0].get("url", "").rstrip("/") if servers else ""
        else:
            base_url = base_url_override

        requests = []
        for path, path_item in spec.get("paths", {}).items():
            for method in ["get", "post", "put", "patch", "delete"]:
                op = path_item.get(method)
                if not op:
                    continue
                url = base_url + self._convert_path_params(path)
                headers = {"Content-Type": "application/json"}
                body = self._extract_openapi3_body(op)
                requests.append({"method": method.upper(), "url": url,
                                  "headers": headers, "body": body, "cookies": {}})
        return requests

    def _extract_openapi3_body(self, op):
        content = op.get("requestBody", {}).get("content", {})
        json_c = content.get("application/json", {})
        example = json_c.get("example") or json_c.get("schema", {}).get("example")
        if example:
            return example
        schema = json_c.get("schema", {})
        if schema.get("properties"):
            return self._example_from_schema(schema)
        return None

    # ── Swagger 2.0 ──────────────────────────────────────────────────
    def _parse_swagger2(self, spec, base_url_override):
        if not base_url_override:
            host      = spec.get("host", "")
            scheme    = (spec.get("schemes", ["https"]) or ["https"])[0]
            base_path = spec.get("basePath", "").rstrip("/")
            base_url  = f"{scheme}://{host}{base_path}"
        else:
            base_url = base_url_override

        requests = []
        for path, path_item in spec.get("paths", {}).items():
            for method in ["get", "post", "put", "patch", "delete"]:
                op = path_item.get(method)
                if not op:
                    continue
                url  = base_url + self._convert_path_params(path)
                body = None
                for param in op.get("parameters", []):
                    if param.get("in") == "body":
                        s = param.get("schema", {})
                        body = s.get("example") or (self._example_from_schema(s) if s.get("properties") else None)
                requests.append({"method": method.upper(), "url": url,
                                  "headers": {"Content-Type": "application/json"}, "body": body, "cookies": {}})
        return requests

    # ── Postman v2.1 ─────────────────────────────────────────────────
    def _parse_postman(self, collection, base_url_override):
        requests = []
        self._walk_postman(collection.get("item", []), requests, base_url_override)
        return requests

    def _walk_postman(self, items, requests, base_url_override):
        for item in items:
            if "item" in item:
                self._walk_postman(item["item"], requests, base_url_override)
                continue
            req    = item.get("request", {})
            method = req.get("method", "GET").upper()
            url    = self._postman_url(req.get("url", ""), base_url_override)
            headers = {h["key"]: h["value"] for h in req.get("header", []) if not h.get("disabled")}
            body    = self._postman_body(req.get("body", {}))
            requests.append({"method": method, "url": url, "headers": headers,
                              "body": body, "cookies": {}})

    def _postman_url(self, url_data, base_url_override):
        raw = url_data.get("raw", "") if isinstance(url_data, dict) else str(url_data)
        if base_url_override:
            raw = re.sub(r'https?://[^/]+', base_url_override, raw)
        return raw

    def _postman_body(self, body_data):
        if not body_data:
            return None
        mode = body_data.get("mode", "")
        if mode == "raw":
            try:
                return json.loads(body_data.get("raw", ""))
            except Exception:
                return body_data.get("raw")
        if mode == "urlencoded":
            return {i["key"]: i["value"] for i in body_data.get("urlencoded", []) if not i.get("disabled")}
        return None

    # ── helpers ───────────────────────────────────────────────────────
    def _convert_path_params(self, path):
        return re.sub(r"\{(\w+)\}", r"{{\1}}", path)

    def _example_from_schema(self, schema):
        example = {}
        type_map = {"string": "example", "integer": 0, "number": 0.0,
                    "boolean": True, "array": [], "object": {}}
        for field, fs in schema.get("properties", {}).items():
            t = fs.get("type", "string")
            example[field] = fs.get("example", type_map.get(t, "example"))
        return example

import re, json, time, requests
from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class ChainedAPIExecutor(Component):
    display_name = "Chained API Executor v2.1"
    description = "Executes chained API requests with retry logic and exponential backoff."
    icon = "play"

    EXTRACT_KEYS = ["token","access_token","bookingid","id","userId","user_id","sessionId","orderId"]

    inputs = [
        MessageTextInput(name="parsed_json",     display_name="Parsed JSON"),
        MessageTextInput(name="seed_variables",  display_name="Seed Variables (optional)", value="{}"),
        MessageTextInput(name="max_retries",     display_name="Max Retries", value="2",
                         info="Retry attempts on failure (0 = no retry)"),
        MessageTextInput(name="retry_on",        display_name="Retry on Status Codes", value="500,502,503,504",
                         info="Comma-separated HTTP status codes that trigger a retry"),
        MessageTextInput(name="backoff_ms",      display_name="Initial Backoff (ms)", value="500",
                         info="Wait before first retry. Doubles each attempt: 500→1000→2000ms"),
    ]
    outputs = [Output(display_name="Results", name="results", method="execute")]

    def execute(self) -> Message:
        raw = self.parsed_json
        if hasattr(raw, "text"):
            raw = raw.text
        raw = str(raw).strip()
        if raw.startswith("```"):
            lines = raw.split("\n")
            raw = "\n".join(lines[1:-1] if lines[-1].strip() == "```" else lines[1:])

        try:
            requests_list = json.loads(raw)
        except Exception as e:
            return Message(text=json.dumps({"error": str(e), "results": [], "variables_extracted": {}}))

        if not isinstance(requests_list, list):
            requests_list = [requests_list]

        try:    store = json.loads(self.seed_variables or "{}")
        except: store = {}
        try:    max_retries = int(self.max_retries or 2)
        except: max_retries = 2
        try:    retry_statuses = {int(s.strip()) for s in (self.retry_on or "500,502,503,504").split(",") if s.strip()}
        except: retry_statuses = {500, 502, 503, 504}
        try:    backoff_ms = int(self.backoff_ms or 500)
        except: backoff_ms = 500

        session = requests.Session()
        results = []

        for req in requests_list:
            req    = self._resolve(req, store)
            method = req.get("method", "GET").upper()
            url    = req.get("url", "")
            headers = req.get("headers") or {}
            body    = req.get("body")
            cookies = req.get("cookies") or {}

            result = self._with_retry(
                session, method, url, headers, body, cookies,
                max_retries, retry_statuses, backoff_ms
            )

            if isinstance(result.get("response"), dict):
                for key in self.EXTRACT_KEYS:
                    if key in result["response"]:
                        store[key] = result["response"][key]

            result["resolved_with"] = dict(store)
            results.append(result)

        session.close()
        return Message(text=json.dumps({
            "results": results,
            "total": len(results),
            "variables_extracted": store
        }))

    def _with_retry(self, session, method, url, headers, body, cookies, max_retries, retry_statuses, backoff_ms):
        last = None
        for attempt in range(max_retries + 1):
            if attempt > 0:
                time.sleep((backoff_ms * (2 ** (attempt - 1))) / 1000)
            start = time.time()
            try:
                resp = session.request(
                    method, url, headers=headers,
                    json=body if isinstance(body, dict) else None,
                    data=body if isinstance(body, str) else None,
                    cookies=cookies, timeout=30
                )
                duration = round((time.time() - start) * 1000, 2)
                try:    resp_body = resp.json()
                except: resp_body = resp.text

                last = {"method": method, "url": url, "status_code": resp.status_code,
                        "duration_ms": duration, "response": resp_body,
                        "retries": attempt, "error": None}

                if resp.status_code in retry_statuses and attempt < max_retries:
                    continue
                return last

            except requests.exceptions.Timeout:
                last = {"method": method, "url": url, "status_code": None,
                        "duration_ms": 30000, "response": None,
                        "retries": attempt, "error": "TIMEOUT"}
            except Exception as e:
                last = {"method": method, "url": url, "status_code": None,
                        "duration_ms": 0, "response": None,
                        "retries": attempt, "error": str(e)}
        return last

    def _resolve(self, obj, store):
        text     = json.dumps(obj)
        resolved = re.sub(r"\{\{(\w+)\}\}", lambda m: str(store.get(m.group(1), m.group(0))), text)
        try:    return json.loads(resolved)
        except: return obj

import json
import re
import os
import operator
from datetime import datetime
from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class ValidatorReporter(Component):
    display_name = "Validator + Reporter v2.1"
    description = "Validates API responses with SLA checks and performance summary."
    icon = "file-text"

    inputs = [
        MessageTextInput(name="execution_results", display_name="Execution Results"),
        MessageTextInput(name="schemas_json",      display_name="Field Schemas (JSON)",         value="{}"),
        MessageTextInput(name="assertions_json",   display_name="Assertions (JSON)",             value="[]"),
        MessageTextInput(name="expected_status",   display_name="Expected Status Codes (JSON)",  value="{}"),
        MessageTextInput(name="sla_thresholds",    display_name="SLA Thresholds ms (JSON)",      value="{}",
                         info='Max response time per endpoint e.g. {"POST.*auth$": 3000}'),
        MessageTextInput(name="output_dir",        display_name="Output Directory",              value="reports"),
    ]

    outputs = [Output(display_name="Report Summary", name="summary", method="run")]

    OPS = {
        "==": operator.eq, "!=": operator.ne,
        ">":  operator.gt, ">=": operator.ge,
        "<":  operator.lt, "<=": operator.le,
    }

    def run(self) -> Message:
        raw = self.execution_results
        if hasattr(raw, "text"):
            raw = raw.text
        raw = str(raw).strip()
        if raw.startswith("```"):
            lines = raw.split("\n")
            raw = "\n".join(lines[1:-1] if lines[-1].strip() == "```" else lines[1:])

        try:
            data    = json.loads(raw)
            results = data.get("results", [])
        except Exception as e:
            return Message(text=f"Could not parse execution results: {e}\nReceived: {raw[:200]}")

        try:    schemas         = json.loads(self.schemas_json or "{}")
        except: schemas         = {}
        try:    assertions      = json.loads(self.assertions_json or "[]")
        except: assertions      = []
        try:    expected_status = json.loads(self.expected_status or "{}")
        except: expected_status = {}
        try:    sla_thresholds  = json.loads(self.sla_thresholds or "{}")
        except: sla_thresholds  = {}

        report = [self._validate_one(r, schemas, assertions, expected_status, sla_thresholds) for r in results]

        total  = len(report)
        passed = sum(1 for r in report if r["overall"] == "PASS")
        failed = total - passed
        summary = {
            "total": total, "passed": passed, "failed": failed,
            "pass_rate": f"{round((passed/total)*100)}%" if total else "0%",
        }

        out_dir = self.output_dir or "reports"
        os.makedirs(out_dir, exist_ok=True)
        ts  = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
        now = datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S UTC")

        html_path = os.path.join(out_dir, f"report_{ts}.html")
        json_path = os.path.join(out_dir, f"report_{ts}.json")
        md_path   = os.path.join(out_dir, f"report_{ts}.md")

        self._write_html(html_path, summary, report, now)
        self._write_json(json_path, {"summary": summary, "results": report}, now)
        self._write_markdown(md_path, summary, report, now)

        durations = [r["duration_ms"] for r in report if r.get("duration_ms") is not None]
        perf_summary = ""
        if durations:
            perf_summary = (
                f"\nPERFORMANCE SUMMARY:"
                f"\n   avg: {round(sum(durations)/len(durations), 2)}ms"
                f" | min: {min(durations)}ms"
                f" | max: {max(durations)}ms"
            )

        endpoint_lines = []
        for r in report:
            icon       = "✅" if r["overall"] == "PASS" else "❌"
            retry_info = f" [retried {r.get('retries')} time(s)]" if r.get("retries", 0) > 0 else ""
            endpoint_lines.append(
                f"\n{icon} {r['method']} {r['url']} — {r['status_code']} ({r['duration_ms']}ms) — {r['overall']}{retry_info}"
            )
            for c in r.get("checks", []):
                s_icon = "✅" if c["status"] == "PASS" else "❌"
                endpoint_lines.append(f"   {s_icon} {c['check']}: {c['detail']}")

        text = (
            f"timestamp: {now}\n"
            f"total: {total} | passed: {passed} | failed: {failed} | pass_rate: {summary['pass_rate']}\n"
            f"Reports saved: HTML={html_path} | JSON={json_path} | MD={md_path}"
            f"{perf_summary}\n"
            f"\nENDPOINT DETAILS:"
            + "\n".join(endpoint_lines)
        )

        return Message(text=text)

    def _validate_one(self, result, schemas, assertions, expected_status, sla_thresholds):
        url, method   = result.get("url", ""), result.get("method", "")
        method_url    = f"{method} {url}"
        status, body  = result.get("status_code"), result.get("response")
        duration_ms   = result.get("duration_ms") or 0
        checks = []

        if result.get("error"):
            checks.append({"check": "connectivity", "status": "FAIL", "detail": result["error"]})
        else:
            checks.append({"check": "connectivity", "status": "PASS",
                           "detail": f"HTTP {status} in {duration_ms}ms"})

        for pattern, exp in expected_status.items():
            if self._matches(method_url, pattern):
                ok = status == exp
                checks.append({"check": "status_code",
                                "status": "PASS" if ok else "FAIL",
                                "detail": f"expected {exp}, got {status}"})

        for pattern, threshold in sla_thresholds.items():
            if self._matches(method_url, pattern):
                ok = duration_ms <= threshold
                checks.append({"check": f"sla:{threshold}ms",
                                "status": "PASS" if ok else "FAIL",
                                "detail": f"{duration_ms}ms {'≤' if ok else '>'} {threshold}ms SLA threshold"})

        schema = self._find(method_url, schemas)
        if schema and isinstance(body, dict):
            for field in schema.get("required", []):
                present = field in body and body[field] is not None
                checks.append({"check": f"required:{field}",
                               "status": "PASS" if present else "FAIL",
                               "detail": f"'{field}' {'present' if present else 'MISSING'}"})
            for field, etype in schema.get("types", {}).items():
                if field in body:
                    atype = type(body[field]).__name__
                    checks.append({"check": f"type:{field}",
                                   "status": "PASS" if atype == etype else "FAIL",
                                   "detail": f"expected {etype}, got {atype}"})

        for a in assertions:
            if self._matches(method_url, a.get("url", "")):
                checks.append(self._assert(body, a))

        overall = "PASS" if all(c["status"] == "PASS" for c in checks) else "FAIL"
        return {"method": method, "url": url, "status_code": status,
                "duration_ms": duration_ms, "retries": result.get("retries", 0),
                "overall": overall, "checks": checks}

    def _find(self, method_url, schemas):
        for p, s in schemas.items():
            if self._matches(method_url, p):
                return s
        return None

    def _matches(self, method_url, pattern):
        return pattern in method_url or bool(re.search(pattern, method_url))

    def _assert(self, body, a):
        field, op_str = a.get("field", ""), a.get("operator", "==")
        expected      = a.get("value")
        label         = a.get("label", f"{field} {op_str} {expected}")
        actual        = self._get(body, field)
        op_fn         = self.OPS.get(op_str)
        if not op_fn:
            return {"check": f"assert:{label}", "status": "FAIL", "detail": f"Unknown operator: {op_str}"}
        try:    passed = op_fn(actual, expected)
        except: passed = False
        return {"check": f"assert:{label}",
                "status": "PASS" if passed else "FAIL",
                "detail": f"{field}={actual!r} {op_str} {expected!r}"}

    def _get(self, body, field):
        cur = body
        for part in field.split("."):
            cur = cur.get(part) if isinstance(cur, dict) else None
        return cur

    def _write_html(self, path, summary, results, now):
        rows = ""
        for r in results:
            color  = "#22c55e" if r["overall"] == "PASS" else "#ef4444"
            bg     = "#dcfce7" if r["overall"] == "PASS" else "#fee2e2"
            retry  = f' <span style="color:#f59e0b">↻ {r["retries"]} retry</span>' if r.get("retries", 0) > 0 else ""
            checks = "".join(
                f'<li style="color:{"green" if c["status"]=="PASS" else "red"}">'
                f'{"✅" if c["status"]=="PASS" else "❌"} {c["check"]}: {c["detail"]}</li>'
                for c in r.get("checks", [])
            )
            rows += (
                f"<tr><td><b>{r['method']}</b></td><td>{r['url']}</td>"
                f"<td>{r['status_code']}</td><td>{r['duration_ms']}ms{retry}</td>"
                f"<td><span style='background:{bg};color:{color};padding:3px 10px;"
                f"border-radius:12px;font-weight:700'>{r['overall']}</span></td>"
                f"<td><ul style='margin:0;padding-left:16px'>{checks}</ul></td></tr>"
            )

        html = f"""<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>API Contract Report</title>
<style>
  body{{font-family:-apple-system,sans-serif;margin:0;background:#f5f7fa}}
  header{{background:#1a1a2e;color:#fff;padding:24px 32px}}
  h1{{margin:0;font-size:1.5rem}} p{{margin:4px 0 0;opacity:.7}}
  .cards{{display:flex;gap:16px;padding:24px 32px}}
  .card{{background:#fff;border-radius:10px;padding:20px 28px;box-shadow:0 2px 8px rgba(0,0,0,.08)}}
  .num{{font-size:2rem;font-weight:700}} .lbl{{font-size:.8rem;opacity:.6}}
  table{{width:calc(100% - 64px);margin:0 32px 32px;border-collapse:collapse;
         background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)}}
  th{{background:#1a1a2e;color:#fff;padding:12px 16px;text-align:left;font-size:.85rem}}
  td{{padding:12px 16px;border-bottom:1px solid #f0f0f0;font-size:.85rem;vertical-align:top}}
</style></head>
<body>
<header><h1>API Contract Validation Report v2.1</h1><p>Generated: {now}</p></header>
<div class="cards">
  <div class="card"><div class="num" style="color:#1a1a2e">{summary['total']}</div><div class="lbl">Total</div></div>
  <div class="card"><div class="num" style="color:#22c55e">{summary['passed']}</div><div class="lbl">Passed</div></div>
  <div class="card"><div class="num" style="color:#ef4444">{summary['failed']}</div><div class="lbl">Failed</div></div>
  <div class="card"><div class="num" style="color:#6366f1">{summary['pass_rate']}</div><div class="lbl">Pass Rate</div></div>
</div>
<table>
  <thead><tr><th>Method</th><th>URL</th><th>HTTP</th><th>Duration</th><th>Result</th><th>Checks</th></tr></thead>
  <tbody>{rows}</tbody>
</table>
</body></html>"""
        with open(path, "w", encoding="utf-8") as f:
            f.write(html)

    def _write_json(self, path, data, now):
        data["generated_at"] = now
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)

    def _write_markdown(self, path, summary, results, now):
        lines = [
            "# API Contract Validation Report v2.1",
            f"\n**Generated:** {now}\n",
            "| Total | Passed | Failed | Pass Rate |",
            "|-------|--------|--------|-----------|",
            f"| {summary['total']} | {summary['passed']} | {summary['failed']} | {summary['pass_rate']} |",
            "\n## Results\n",
            "| Method | URL | HTTP | Duration | Retries | Result |",
            "|--------|-----|------|----------|---------|--------|",
        ]
        for r in results:
            icon = "✅" if r["overall"] == "PASS" else "❌"
            lines.append(
                f"| {r['method']} | {r['url']} | {r['status_code']} | {r['duration_ms']}ms | {r.get('retries',0)} | {icon} {r['overall']} |"
            )
        lines.append("\n### Check Details\n")
        for r in results:
            lines.append(f"#### {r['method']} {r['url']}")
            for c in r.get("checks", []):
                icon = "✅" if c["status"] == "PASS" else "❌"
                lines.append(f"- {icon} **{c['check']}**: {c['detail']}")
            lines.append("")
        with open(path, "w", encoding="utf-8") as f:
            f.write("\n".join(lines))
